style.css:
@-moz-document domain("youtube.com") {
/* Toggle button */
  #videoOnlyToggle {
    position: fixed;
    top: 10px;
    left: 10px;
    z-index: 99999;
    padding: 6px 12px;
    background-color: rgba(0,0,0,0.7);
    color: white;
    font-size: 12px;
    font-family: sans-serif;
    border: 1px solid #ccc;
    border-radius: 4px;
    cursor: pointer;
    user-select: none;
  }

  body::before {
    content: "Video Only Mode";
    display: block;
    position: fixed;
    top: 10px;
    left: 10px;
    z-index: 99998;
    background-color: transparent;
    padding: 0;
  }

  body[data-videoonly="true"] #info,
  body[data-videoonly="true"] #secondary,
  body[data-videoonly="true"] #comments,
  body[data-videoonly="true"] ytd-merch-shelf-renderer,
  body[data-videoonly="true"] #meta-contents,
  body[data-videoonly="true"] ytd-video-secondary-info-renderer,
  body[data-videoonly="true"] ytd-video-primary-info-renderer,
  body[data-videoonly="true"] #related,
  body[data-videoonly="true"] #below,
  body[data-videoonly="true"] #menu-container,
  body[data-videoonly="true"] ytd-menu-renderer,
  body[data-videoonly="true"] .ytp-chrome-top,
  body[data-videoonly="true"] .ytp-chrome-bottom,
  body[data-videoonly="true"] .ytp-show-cards-title,
  body[data-videoonly="true"] .ytp-endscreen-content,
  body[data-videoonly="true"] .ytp-ce-element {
    display: none !important;
  }

  body[data-videoonly="true"] #videoOnlyToggle::after {
    content: " (ON)";
    color: #0f0;
  }

  body[data-videoonly="false"] #videoOnlyToggle::after {
    content: " (OFF)";
    color: #f00;
  }
}
